using System.ComponentModel.DataAnnotations; using LibrarySystem.Application.Catalog; using LibrarySystem.Application.Security; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages;
namespace LibrarySystem.Pages.Dashboards;
[Authorize(Policy=PolicyNames.ManageCatalog)] public sealed class InventoryModel(IInventoryService service):PageModel
{ [BindProperty(SupportsGet=true)] public long? Id{get;set;} public IReadOnlyCollection<InventorySessionDto> Sessions{get;private set;}=[]; public InventorySessionDto? Session{get;private set;} public async Task OnGetAsync(CancellationToken t)=>await Load(t); public async Task<IActionResult> OnPostStartAsync(string name,CancellationToken t){try{var x=await service.StartAsync(name,t);return RedirectToPage(new{Id=x.Id});}catch(ValidationException e){TempData["ErrorMessage"]=e.Message;return RedirectToPage();}} public async Task<IActionResult> OnPostScanAsync(long id,string barcode,CancellationToken t){try{await service.ScanAsync(id,barcode,t);TempData["StatusMessage"]=$"Copy {barcode} was marked found.";}catch(Exception e)when(e is ValidationException or KeyNotFoundException){TempData["ErrorMessage"]=e.Message;}return RedirectToPage(new{Id=id});} public async Task<IActionResult> OnPostCompleteAsync(long id,CancellationToken t){await service.CompleteAsync(id,t);return RedirectToPage(new{Id=id});} public async Task<IActionResult> OnPostReconcileAsync(long id,long copyId,CancellationToken t){try{await service.ReconcileMissingAsync(id,copyId,t);TempData["StatusMessage"]="The missing copy was reconciled as lost.";}catch(ValidationException e){TempData["ErrorMessage"]=e.Message;}return RedirectToPage(new{Id=id});} public async Task<IActionResult> OnPostWithdrawAsync(long id,long copyId,string reason,CancellationToken t){try{await service.WithdrawAsync(copyId,reason,t);TempData["StatusMessage"]="The copy was withdrawn with its history preserved.";}catch(ValidationException e){TempData["ErrorMessage"]=e.Message;}return RedirectToPage(new{Id=id});} private async Task Load(CancellationToken t){Sessions=await service.ListAsync(t);if(Id.HasValue)Session=await service.GetAsync(Id.Value,t);}}
